function withdraw(uint256 amount) external {
    if (msg.sender != owner) revert NotOwner(msg.sender);
    if (amount > total) revert Insufficient(amount, total);
    total -= amount;
    (bool ok,) = payable(owner).call{value: amount}("");
    if (!ok) revert TransferFailed();
}

pragma solidity ^0.8.20;
contract LearningRegistryV1 {
    error NotOwner(address caller); error Insufficient(uint256 requested, uint256 available); error TransferFailed();
    address public immutable owner;
    struct Chapter { uint256 id; string title; bool active; }
    Chapter[] public chapters; uint256 public total;
    event ChapterAdded(uint256 indexed id, string title); event Deposited(address indexed user, uint256 amount); event Withdrawn(uint256 amount);
    constructor() { owner = msg.sender; }
    modifier onlyOwner() { if (msg.sender != owner) revert NotOwner(msg.sender); _; }
    function addChapter(string calldata title) external onlyOwner { uint256 id = chapters.length; chapters.push(Chapter(id, title, true)); emit ChapterAdded(id, title); }
    function deposit() external payable { require(msg.value > 0, "zero deposit"); total += msg.value; emit Deposited(msg.sender, msg.value); }
    function withdraw(uint256 amount) external onlyOwner { if (amount > total) revert Insufficient(amount, total); total -= amount; (bool ok,) = payable(owner).call{value: amount}(""); if (!ok) revert TransferFailed(); emit Withdrawn(amount); }
}

